# -*- coding: utf-8 -*-
"""R63 S6 席生成脚本：B16/B17/B18 共60例预测落盘。带例数/id集断言。"""
import json, os
BASE='/home/hatch/workspace/divination/benchmark/phase3'
OUT=f'{BASE}/runs/round63/predictions'
os.makedirs(OUT, exist_ok=True)
batches=json.load(open(f'{BASE}/runs/round63/batches.json'))
MYIDS=batches['B16']+batches['B17']+batches['B18']
assert len(MYIDS)==60 and len(set(MYIDS))==60, MYIDS

