def ly_basis(cid):
    c,p,y,e,t = LY[cid][:5]
    card=json.load(open(f'{BASE}/inputs-dev12/{cid}.json'))
    trad=card.get('tradition')
    first=f"tradition: {trad}（输入卡自带 tradition 字段，逐例读卡自决：六爻）"
    basis="\n".join([
        first,
        "systems_used: 六爻纳甲（主法，方法自选；按快照 chinese-liuyao-meihua.md 六爻篇）",
        f"已载面表：1主问面→已断（主断见 prediction_text）；2题面事件面→已断/并入主断；3关系面→{y}；4对象面→已按用神指代链核；5应期面→已断（见应期行）；锚点转应核：题面卦名/干支为盘面锚点，直读与转应已并核，无文字锚点转应另计者注明于证据行；余面题面未载。",
        f"对象对齐：{y}",
        f"证据链：{e}",
        f"应期：{t}",
        "收束复核（R61-REV1）：二路复推与粒度核已并入应期行留痕；方向锁定：复核未改终局方向。列面—证据双闸（calibration第五节）自R61起标失效存档、本轮不作强制执行，仅以(n)双核为准留痕。",
    ])
    cm,ru,di,reason=TRIG[cid]
    return {"case_id":cid,"prediction_text":p,"basis":basis,"confidence":c,
            "trigger":{"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}}

