def mh_basis(cid):
    c,p,e = MH[cid]
    card=json.load(open(f'{BASE}/inputs-dev12/{cid}.json'))
    if 'tradition' in card: first=f"tradition: {card['tradition']}（输入卡自带 tradition 字段，逐例读卡自决：梅花易数）"
    elif 'system' in card: first=f"tradition: 无 tradition 字段（输入卡以 system 字段载 {card['system']}，据此及题面体裁自决：梅花易数）"
    else: first="tradition: 无 tradition 字段（输入卡无 tradition/system 字段，据题面体裁自决：梅花易数）"
    basis="\n".join([first,
      "systems_used: 梅花易数（主法，方法自选；按快照 chinese-liuyao-meihua.md 梅花篇；《梅花易数》托名文本、体系照用出处存疑照实标注）",
      f"已载面表：主问面→已断；事件/对象面→已断（见证据行）；应期面→已断；锚点转应核：题面物象锚点直读与转应并列核于证据行；余面题面未载。",
      f"证据链（体用/辞义/事实/对象）：{e}",
      "收束复核（R61-REV1）：具体断项粒度核已并入证据行（单指针断项已降档表述）；无六爻式应期三路，本法应期以体用/爻位/卦数取点并双层表达，已留痕。"])
    return {"case_id":cid,"prediction_text":p,"basis":basis,"confidence":c,
            "trigger":{"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}}

