def mp_basis(cid):
    c,p,e = MP[cid]
    basis="\n".join([
      "tradition: 无 tradition 字段（输入卡无 tradition/system 字段，据题面体裁自决：现代命理/选举占，MP-016 据题面明示以字问卜自决为测字、MP-012 据 setting 载塔罗及文王圣卦而盘面未载）",
      "systems_used: 题面事实分析为主（事实优先序）、命理年运/局势框架为参（方法自选/混用）；MP-016 为测字（拆字取象）",
      "已载面表：主问面→已断；题面局势/民调/声势面→已断并入证据行；关系面（对手/搭档）→已断；应期面→以选举日程定点已断；余面题面未载。",
      f"证据链：{e}",
      "输入残损：本卡无卦盘/牌面/出生年月日时等盘面字段（仅出生年与局势描述），无从按体系排盘，照实注明并已降置信，不臆补盘面。收束复核（R61-REV1）：数量/排序类断项粒度已在证据行核（指针不足者降为区间/量级表述）。"])
    return {"case_id":cid,"prediction_text":p,"basis":basis,"confidence":c,
            "trigger":{"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}}

written=[]
for cid in MYIDS:
    if cid.startswith('LY'): obj=ly_basis(cid)
    elif cid.startswith('MH'): obj=mh_basis(cid)
    else: obj=mp_basis(cid)
    assert obj['case_id']==cid
    assert 0<=obj['confidence']<=1
    path=f'{OUT}/{cid}.json'
    with open(path,'w',encoding='utf-8') as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
    written.append(path)
assert len(written)==60
print('WROTE',len(written))
for p in written: print(p, os.path.getsize(p))
